package com.wanyuecity.energy.operation;
import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
import java.sql.Date;import java.sql.Timestamp;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class OperationClearanceService{
 private final JdbcTemplate jdbc;private final OperationClearanceTemplateService templates;
 public OperationClearanceService(JdbcTemplate jdbc,OperationClearanceTemplateService templates){this.jdbc=jdbc;this.templates=templates;}
 public Map<String,Object>currentPeriod(){LocalDateTime now=LocalDateTime.now();LocalDate d;if(!now.toLocalTime().isBefore(LocalTime.of(21,0)))d=now.toLocalDate();else if(now.toLocalTime().isBefore(LocalTime.of(9,0)))d=now.toLocalDate().minusDays(1);else return Map.of("open",false,"message","日清提交时间为每日21:00至次日09:00");return Map.of("open",true,"periodDate",d.toString(),"periodStart",d.atTime(21,0),"periodEnd",d.plusDays(1).atTime(9,0));}
 @Transactional public Map<String,Object>submit(String token,Map<String,Object>b,String username){
  Map<String,Object>p=currentPeriod();if(!Boolean.TRUE.equals(p.get("open")))throw bad(Objects.toString(p.get("message")));
  Map<String,Object>s=one("SELECT s.id,s.business_type businessType,s.status,COALESCE(NULLIF(m.merchant_name,''),NULLIF(s.stall_name,''),s.stall_code) merchantName FROM stall s LEFT JOIN merchant m ON m.id=s.current_merchant_id WHERE s.operation_qr_token=?",token);
  if(!"OCCUPIED".equals(s.get("status")))throw bad("当前铺位不是在用状态，不计入日清");if("CK".equalsIgnoreCase(Objects.toString(s.get("businessType"),"")))throw bad("仓库类型铺位不需要提交日清");
  var ev=templates.evaluate(token,b.get("answers"));Map<String,Object>a=ev.answers();boolean electricity=flag(a,"electricityOff",true),water=flag(a,"waterOff",true),gas=flag(a,"gasOff",true),door=flag(a,"doorClosed",true);String desc=Objects.toString(a.getOrDefault("exceptionDescription",b.get("exceptionDescription")),"").trim();String status=ev.normal()?"NORMAL":"ABNORMAL";if(!ev.normal()&&desc.isBlank())throw bad("存在异常项目时请填写异常说明");
  Map<String,Object>u=one("SELECT id,COALESCE(NULLIF(display_name,''),username) displayName FROM sys_user WHERE username=?",username);List<Map<String,Object>>mr=jdbc.queryForList("SELECT r.responsible_user_id managerId,COALESCE(NULLIF(u.display_name,''),u.username) managerName FROM operation_merchant_responsibility r JOIN sys_user u ON u.id=r.responsible_user_id WHERE r.stall_id=? AND r.status='ACTIVE'",s.get("id"));Object mid=mr.isEmpty()?null:mr.get(0).get("managerId"),mn=mr.isEmpty()?null:mr.get(0).get("managerName");LocalDate d=LocalDate.parse(Objects.toString(p.get("periodDate")));String no="QC"+d.format(DateTimeFormatter.BASIC_ISO_DATE)+"-"+s.get("id");
  jdbc.update("INSERT INTO operation_clearance_record(record_no,stall_id,period_date,period_start,period_end,submitter_user_id,submitter_name,merchant_name_snapshot,manager_user_id,manager_name_snapshot,template_id,template_version,template_name_snapshot,answers_json,electricity_off,water_off,gas_off,door_closed,exception_description,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE submitter_user_id=VALUES(submitter_user_id),submitter_name=VALUES(submitter_name),merchant_name_snapshot=VALUES(merchant_name_snapshot),manager_user_id=VALUES(manager_user_id),manager_name_snapshot=VALUES(manager_name_snapshot),template_id=VALUES(template_id),template_version=VALUES(template_version),template_name_snapshot=VALUES(template_name_snapshot),answers_json=VALUES(answers_json),electricity_off=VALUES(electricity_off),water_off=VALUES(water_off),gas_off=VALUES(gas_off),door_closed=VALUES(door_closed),exception_description=VALUES(exception_description),status=VALUES(status),submitted_at=CURRENT_TIMESTAMP(3)",no,s.get("id"),Date.valueOf(d),Timestamp.valueOf(d.atTime(21,0)),Timestamp.valueOf(d.plusDays(1).atTime(9,0)),u.get("id"),u.get("displayName"),s.get("merchantName"),mid,mn,ev.templateId(),ev.version(),ev.name(),ev.answersJson(),electricity,water,gas,door,desc,status);
  return one("SELECT id,record_no recordNo,status,submitted_at submittedAt FROM operation_clearance_record WHERE stall_id=? AND period_date=?",s.get("id"),Date.valueOf(d));
 }
 public Map<String,Object>page(String username,boolean all,String keyword,String date,int pageNum,int pageSize){Map<String,Object>u=one("SELECT id FROM sys_user WHERE username=?",username);int pn=Math.max(1,pageNum),ps=Math.min(100,Math.max(10,pageSize));List<Object>a=new ArrayList<>();StringBuilder w=new StringBuilder(" WHERE 1=1");if(!all){w.append(" AND (c.submitter_user_id=? OR c.manager_user_id=?)");a.add(u.get("id"));a.add(u.get("id"));}if(date!=null&&!date.isBlank()){w.append(" AND c.period_date=?");a.add(Date.valueOf(date));}if(keyword!=null&&!keyword.isBlank()){w.append(" AND (s.stall_code LIKE ? OR c.merchant_name_snapshot LIKE ?)");String k="%"+keyword.trim()+"%";a.add(k);a.add(k);}String from=" FROM operation_clearance_record c JOIN stall s ON s.id=c.stall_id";Long total=jdbc.queryForObject("SELECT COUNT(*)"+from+w,Long.class,a.toArray());a.add(ps);a.add((pn-1)*ps);List<Map<String,Object>>rows=jdbc.queryForList("SELECT c.id,c.record_no recordNo,c.period_date periodDate,s.stall_code stallCode,c.merchant_name_snapshot merchantName,c.submitter_name submitterName,c.manager_name_snapshot managerName,c.template_name_snapshot templateName,c.answers_json answersJson,c.electricity_off electricityOff,c.water_off waterOff,c.gas_off gasOff,c.door_closed doorClosed,c.exception_description exceptionDescription,c.status,c.submitted_at submittedAt"+from+w+" ORDER BY c.period_date DESC,c.submitted_at DESC LIMIT ? OFFSET ?",a.toArray());return Map.of("records",rows,"total",total==null?0:total,"current",pn,"size",ps);}
 private boolean flag(Map<String,Object>a,String k,boolean d){return a.containsKey(k)?Boolean.parseBoolean(Objects.toString(a.get(k))):d;}private Map<String,Object>one(String q,Object...a){List<Map<String,Object>>r=jdbc.queryForList(q,a);if(r.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"数据不存在");return r.get(0);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}
